) AS (
  VALUES 
    (438::BIGINT, 'Enseña bien, sabe mucho de distribución de planta. Deja todo para lo ultimo, tanto la asignación de trabajos como la entrega de notas. Al final va a pasar porque a todo le pone 100 despues.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, '60ac82b891045ea0c2b091fcf1ee937641be324cd2d45850118d6e9f7c4b038c'::TEXT, ARRAY[1760]::BIGINT[]),
    (438::BIGINT, 'Con garces usted pasa 100%, se aprende lo justo, el sabe bastante y si usted le pregunta le explica más en profundidad, si quiere tirársela al suave es buena opción. Entrega las notas de toda la última semana, así que no espere retroalimentación'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'f8eeef8c2a29cc8a795cd0c0fece140d005b08cc64a97a6791b56f80b6bfa03f'::TEXT, ARRAY[1757, 1754]::BIGINT[]),
    (438::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'c9caafe3ca02e9094bb18fd9ca0d1ddcda899ea21580a365add0d8827e52dee5'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Con Garcés usted pasa el curso a menos de que sea vago y no vaya a las clases, si quiere aprender solo pregúntele en clase y él con gusto explora más con la materia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '70bc057fd312ce46be7dd248cec719d4cba86ba8f870e084b7b6899348a09d9d'::TEXT, ARRAY[1754]::BIGINT[]),
    (438::BIGINT, 'Excelente Profesor. Entrega todo al final'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-01T00:00:00+00:00'::TIMESTAMPTZ, '686c37cf7055674c29353687c649a5352908426d7fee71a99fc4a75be537c23c'::TEXT, ARRAY[1760]::BIGINT[]),
    (438::BIGINT, 'Hay que ir a todas las clases, deja trabajo en clase y tareas grupales muy sencillas. Los exámenes son un poco enredados pero después da puntos extra y el proyecto es muy fácil. Explica bien porque hace muchos ejemplos en clase, la teoría la ve muy rápido y si entra en exámenes. Se pasa bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5d02fd56c80bdcd69a6b004db708fde82578ad99bf0e89dd82da98a5918f52a9'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'El curso es pasable, pero es necesario llevar la materia al día y hacer consultas al profesor ya que aveces no sabe explicar bien los conceptos en clase.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1382d0e8da485f0eb2488bb9739a27858d7e85b475c34043b5755f798d2a8691'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'Explica bien, las evaluaciones son sencillas y se aprende. Es amable y ayuda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-07T00:00:00+00:00'::TIMESTAMPTZ, '216934c21c41cb116e296afb703c1b77f48955c633bd6af4348bb5a257b0f6c8'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'Buen profe, pero las notas las da hasta el final'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'ec894f3398371b062eb979b8132728fb77995a71c4f2a216d8bfe75b19efddb8'::TEXT, ARRAY[1760]::BIGINT[]),
    (438::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, '1c7ab3150d7e2578d2c1964832cbc48c86969424ee41353d6255b6bea897a9db'::TEXT, ARRAY[2465]::BIGINT[]),
    (438::BIGINT, 'sabe mucho y trata de explicar lo mejor que pueda. En cuestión de aprender, sí se aprende que es la finalidad del curso. Tareas y exámenes de acuerdo a lo que se ve en clase. Puede que las últimas evaluaciones tarde en revisarlas y entregar promedios finales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '5bef040907b92687724221873210f9642e9c7fda823682dfc4b91962dceb1cc5'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'Explica bien y deja casos y tareas extra para ayudar al estudiante. Las evaluaciones son normales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, '6b4487ed4944ab859e246dc7dedbdd74f136770fcf3bd6e9a7678d0c09a99d07'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'Explica bien esta materia, si matricula con él va a aprender y a pasar con buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9034d78b68c307cd02b6ca40468bc05a07b969c9717209afad45eaab008f2ec7'::TEXT, ARRAY[2490]::BIGINT[]),
    (438::BIGINT, 'Se nota que sabe mucho, eso no lo voy a negar. Lo malo es que no revisa ABSOLUTAMENTE NADA hasta semana 17 y pone notas al azar. No lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2726913a5ca6f3ea35559028225349e4cafb47ff513290ef1048d7ed7a784f13'::TEXT, ARRAY[1754]::BIGINT[]),
    (438::BIGINT, 'Es un excelente profesor, era la primer vez que daba el curso en mucho tiempo y lo hizo BIEN. Matricule con él sin miedo pero HAGA LAS COSAS y le irá bien. No tenga miedo, En grupo solo el proyecto(caso) final.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '09dc940592ee4e4309c835ab6d81726bb79378497b6159ab6d5275466cf57efd'::TEXT, ARRAY[1757]::BIGINT[]),
    (438::BIGINT, 'se nota que sabe un montón pero generalmente no sabe cómo darse a explicar bien. Las clases son muy tediosas .Cuesta que revise las cosas en el semestre.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '91740b2f7dc51be7fb33fa8898ea703b61ac2350f8a8a96b3cbc78106a432133'::TEXT, ARRAY[1760]::BIGINT[]),
    (438::BIGINT, 'Excelente profesor. Dura mucho para entregar las cosas, pero es porque lo ponen a dar muchos cursos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-01-14T00:00:00+00:00'::TIMESTAMPTZ, '36c9c346d5d2c1ba245db6ae95997eb912b902fff9baefc19ee22554009b2dc9'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Es buen profe y se nota que sabe de lo que está hablando, pero le cuesta bastante explicarlo de forma clara. Si uno le pide ayuda le explica de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '7af28b019f7efdcd196da7a24eda11f217686fc6cb98a50b5413e2b08a97002a'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, '(Virtual) No se aprende mucho si solo se queda con lo que él da en clase, domina bien algunos temas sin embargo le es difícil explicarlos con claridad(se suele perder o enredar un poco). Califica muy suave, todas las calificaciones las da hasta final de semestre. Es muy llevadero el curso con él.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1ef240391b058626179628075caa40f6a874b024737a5eb5a880a11874656143'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Es buen profe. Estudie y sáquele provecho. Si se relaja, no aprende, es obvio.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '77038187bcff71238219b5f610958e3f2a87c396e4a3c10edde50f6dcd308100'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'El profe es muy bueno explicando la materia, va un poco rápido pero si se le pregunta vuelve a explicar. Califica suave pero hasta el final de semestre. Muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '61d0dfaf35e245149458ce9e4e2f426fd5b680a03d516b92e952f07944e840be'::TEXT, ARRAY[1754]::BIGINT[]),
    (438::BIGINT, 'No se aprende nada, pero el curso se pasa demasiado fácil. Pone las notas hasta el día antes de entrega de actas. Si quiere pasar sin trabajo, él es el profe. Si quiere aprender, no matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '8d5a26baf23f6e6a506484ab8a408a9b06e102f3a1b5ba96df685149ba32aa5d'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Clases largas y aburridas pero se nota que el profe sabe mucho y explica bien. No deja muchas tareas ni exámenes por lo que se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, '5d0a9eb8e43d8b1199c05cf8aaac4c245298409248e6239b765ca50511d0e1dd'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'El profe explica bastante bien, las clases son buenas y completas. Se hacen muy pocas evaluaciones durante el semestre y las califica hasta el puro final, muy fácil sacar nota alta. Si se aprende bastante, pero uno debe de darle seguimiento al curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '5943a8a1b500b2bfdbb8ed9d0bf0120e0d4341942333519e9c666b3ff14212ad'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Es un profesor que sabe mucho se nota. Explica bien. Se atrasa con las entregas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'b32acb7f28dcd58d10af8de6bf35902c2f0c29be1db14743b5a01ad45c5644a2'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Muy buen profesor, se centra en enseñar lo que se puede llegar a utilizar en la vida profesional. Lo único malo es que si tarda bastante en entregar las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'bda906d322dffb11c6445ea891daa706bd9adff9fe30528915c1436f61446561'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, '(virtual) hay que estar detrás del profe para que suba las clases y nunca contesta correos. Deja poca evaluaciones y son fáciles pero sus indicaciones no son claras'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '1816228c867f81734224aa154d6a6cbe934bfaf53b5d3ccbab45c1e779497463'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Malísimo. No terminó de ver la materia del programa. Se saltó el tema de transporte y vio muy poco de pronósticos. Falta a muchas clases y no las repone ni deja trabajo. No revisa nada durante el semestre, pone nota alta el día de la entrega de actas. No se aprende nada. Ivannia es mejor.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9e4c42d1e0d0dcaff69f385a963aabdcc4d3015997f096c531492264327b0d80'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'El curso es muy muy fácil pero no vale la pena porque literal no se aprende nada, el compa súper desorganizado, casi nunca responde correos, se desaparece con las notas y aparece un día antes de la entrega de actas, clases dem lentas y aburridas, no lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'c51a4749d391b7440ff7c9baea23832c9e85d7d37d688e4c31ce6077cbcf20c8'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, '[Virtual] El profe es buena gente y muy accesible, las clases son largas y cansadas. A veces no se le entiende muy bien y dio notas hasta un día antes de entrega de actas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '0dfa90bc19b8198c758d788179fc1917ce3d83222376f52868c54e1e55fc67d0'::TEXT, ARRAY[1719]::BIGINT[]),
    (438::BIGINT, 'Es bastante bueno y accesible pero dura un mundo en dar calificaciones'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '188d663b45e3bc3baed322dd4d7a2ad619db84e5807880080685ea28ca0cf7e3'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Semana 18 y en todo el semestre solo ha revisado una tarea, nadie sabe si pasó o se quedó. Buen profe pero ese aspecto a nadie le gusta :('::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, '150ed8f5d3abcf4dbfebeaea5694a5aef7f7fcdb899a4920f2a1e0a38f2b0166'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'El profe es bueno, pero si tarda mucho en devolver los trabajos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2dde46ab32a98e1b8fa3b3b12cb8bee6fac622fde3769b0be39a8f397fa2cafa'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Explica muy bien y ayuda con las dudas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-29T00:00:00+00:00'::TIMESTAMPTZ, '711a5b18e6594ee7e2c237221affe7d39974be821e9f78c6c527bddbfe17cec9'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Dura demasiado para entregar los trabajos revisados. Explica demasiado rapido. En los examenes aplica cosas que no se vieron en clase. Y no es para nada abierto a recomendaciones, reaccionando de forma impulsiva. Nada recomendado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '491cbde18e8ba5e824a40a9ffb8e277a8814729dd0ec2030ca19e7bd385802c7'::TEXT, ARRAY[3131]::BIGINT[]),
    (438::BIGINT, 'Él explica un poco rápido pero muy claro. Con solo ir a clases se pasa el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'c64cae3e18b29819a1c9c69aa7acd29f53fae046914dc8b328c819bb68a1d515'::TEXT, ARRAY[2490]::BIGINT[]),
    (438::BIGINT, 'Literalmente en virtual el mae es lo más fácil qué hay, básicamente le regala el curso a uno. Meta con él y ya paso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '6d66f5ab7c26ea96c35e19be0cc74fdbaf5804d7cf71b41f7c1446165069c862'::TEXT, ARRAY[1754]::BIGINT[]),
    (438::BIGINT, 'Sin duda es un profesor que sabe lo que habla. Muy amable. Este semestre se atrasó con la entrega de evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '0392d264e447d2ac2192688b7bc98636df65d8490f266744a82ccaa0cdfcf5b9'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Explicando es normal, pero en las evaluaciones hay cosas que ni se vieron bien en el curso. Dura demasiado calificando (quices de febrero lo entrego ya cuando se termino el curso en agosto). No da retroalimentación de las evaluaciones. En general y si quiere aprender algo NO LO RECOMIENDO'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '3127191157889ffd0b2847682e70e37c1dfa43b0034a4f5c0fa552f81b729017'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Dura DEMASIADO revisando, no ha entregado ni el quiz que hicimos en febrero y ya es julio. No es recomendable meter con él, menos si es virtual'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '62ecd2be3e5a6197c13422c71d5577bb059a6af88cf83852b6e6f39f99558bb3'::TEXT, ARRAY[1745]::BIGINT[]),
    (438::BIGINT, 'Es un viejo verde. Cuida mujeres!!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-04-17T00:00:00+00:00'::TIMESTAMPTZ, 'a50044ec577538dd6742dca865bd70235b6fab17238909ce51c03b7388e12005'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Falta ser más claro e indicar lo que pretende o espera de uno como estudiante. Se queda uno con la duda de que realmente espera'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2019-10-12T00:00:00+00:00'::TIMESTAMPTZ, '3a4fff45314e648351688305621a3ed49c02324bed0ebc3390227b3401e50267'::TEXT, ARRAY[1772]::BIGINT[]),
    (438::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'e22b7a633b7fa031113ad54229659c58bc7a15c89c04a37eb839d20b290e3a8d'::TEXT, ARRAY[1728]::BIGINT[]),
    (438::BIGINT, 'Buen profesor. Sabe lo que explica, con él se aprende.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '03c039c8bc0eb1ed11d237522ddd2f5ad9daf4964d39c0b8e30676a2459185f2'::TEXT, ARRAY[1743]::BIGINT[]),
    (438::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'cf5b08c797d74a2f34b10e18e7071cc3394329ff0365c52878cff6dfa894a232'::TEXT, ARRAY[1763]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
